// packages/Core-Go-Backend/pagerank.go
// ARCHITECTURE: SEO AVENGERS 200 - TOPOLOGICAL MATRIX MATCHER (PERRON-FROBENIUS MODEL)
package main

import (
	"context"
	"math"
	"time"
)

type SparseMatrix struct {
	Rows map[string]map[string]float64
}

// Módulos 101-135 y 136-150: Cálculo asíncrono y desacoplado fuera de la ruta de renderizado
func CalculateInternalPageRank(ctx context.Context, matrix SparseMatrix, damping float64, iterations int) map[string]float64 {
	scores := make(map[string]float64)
	nodes := make([]string, 0, len(matrix.Rows))

	for node := range matrix.Rows {
		scores[node] = 1.0 / float64(len(matrix.Rows))
		nodes = append(nodes, node)
	}

	// Bucle acoplado al Guardián: Cancelación por contexto asíncrono si el servidor se satura
	for i := 0; i < iterations; i++ {
		select {
		case <-ctx.Done():
			return scores // Retorna estado seguro anterior
		default:
			nextScores := make(map[string]float64)
			for _, u := range nodes {
				nextScores[u] = (1.0 - damping) / float64(len(nodes))
				for _, v := range nodes {
					if links, exists := matrix.Rows[v]; exists {
						if _, hasLink := links[u]; hasLink {
							nextScores[u] += damping * (scores[v] / float64(len(links)))
						}
					}
				}
			}

			// Validar convergencia L1 para evitar bucles infinitos en el runtime de Nexus
			diff := 0.0
			for _, node := range nodes {
				diff += math.Abs(nextScores[node] - scores[node])
			}
			scores = nextScores
			if diff < 1e-6 {
				break
			}
		}
	}
	return scores
}
